mapper.sql:
EXISTS(
    SELECT 1
    FROM t_user_role user_role
             JOIN t_role_short_domain role_domain
                  ON role_domain.role_id = user_role.role_id
    WHERE user_role.user_id = #{userId}
      AND role_domain.short_domain_id = #{shortDomainId}
) OR EXISTS(
    SELECT 1
    FROM t_user_role user_role
             JOIN t_role_short_domain_group role_domain_group
                  ON role_domain_group.role_id = user_role.role_id
             JOIN t_short_domain_group_member dgd
                  ON dgd.short_domain_group_id = role_domain_group.short_domain_group_id
    WHERE user_role.user_id = #{userId}
      AND dgd.short_domain_id = #{shortDomainId}
) OR EXISTS(
    SELECT 1
    FROM t_user_short_domain user_domain
    WHERE user_domain.user_id = #{userId}
      AND user_domain.short_domain_id = #{shortDomainId}
) OR EXISTS(
    SELECT 1
    FROM t_user_short_domain_group user_domain_group
             JOIN t_short_domain_group_member dgd
                  ON dgd.short_domain_group_id = user_domain_group.short_domain_group_id
    WHERE user_domain_group.user_id = #{userId}
      AND dgd.short_domain_id = #{shortDomainId}
)
